class stringx {
    char data[16];
public:
    stringx(const char *, int = -1);
};

void *operator new(unsigned int, unsigned int, const char *, int);

class FEMenuSystem;
class FEManager;

struct beach_vtable {
    char padding[0x40];
    short adjustment;
    short padding2;
    void (*load)(void *);
};

class BeachFrontEnd {
    char padding[0x74];
    beach_vtable *vtable;
    char remainder[0xF40 - 0x78];
public:
    BeachFrontEnd(FEMenuSystem *, FEManager *, stringx, stringx);
    void Load()
    {
        beach_vtable *table = vtable;
        table->load((char *)this + table->adjustment);
    }
};

struct helpbar_vtable {
    char padding[0x28];
    short adjustment;
    short padding2;
    void (*load_panel)(void *, bool);
};

class HelpbarFE {
    char padding[0xC0];
    helpbar_vtable *vtable;
    char remainder[0x160 - 0xC4];
public:
    HelpbarFE(FEManager *, stringx, stringx);
    void LoadPanel(bool floating = false)
    {
        helpbar_vtable *table = vtable;
        table->load_panel((char *)this + table->adjustment, floating);
    }
};

class FEManager {
    char padding[0x156A0];
    BeachFrontEnd *map;
    HelpbarFE *helpbar;
public:
    void LoadMap();
    void LoadFonts();
    void LoadScores();
};

#define NEW new(0, __FILE__, __LINE__)

void FEManager::LoadMap()
{
	LoadFonts();
	map = NEW BeachFrontEnd(NULL, this, "interface\\map\\", "FE_map.PANEL");
	map->Load();
	LoadScores();
	helpbar = NEW HelpbarFE(this, "levels\\frontend\\overlays\\", "helpbar.PANEL");
	helpbar->LoadPanel();
}
